import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.BWTY_seE.js";const d=JSON.parse('{"title":"AI 动态 · 2026-11-06","description":"","frontmatter":{"title":"AI 动态 · 2026-11-06","date":"2026-11-06T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-06.md","filePath":"news/2026-11/ai-news-2026-11-06.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-06.md"};function i(o,e,l,p,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-06" tabindex="-1">AI 动态 · 2026-11-06 <a class="header-anchor" href="#ai-动态-·-2026-11-06" aria-label="Permalink to &quot;AI 动态 · 2026-11-06&quot;">​</a></h1><blockquote><p>截至 2026-11-06。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="ramp-数据显示-ai-支出停滞-anthropic-临近-ipo-承压" tabindex="-1">Ramp 数据显示 AI 支出停滞，Anthropic 临近 IPO 承压 <a class="header-anchor" href="#ramp-数据显示-ai-支出停滞-anthropic-临近-ipo-承压" aria-label="Permalink to &quot;Ramp 数据显示 AI 支出停滞，Anthropic 临近 IPO 承压&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/52b0fdc26585.webp" alt="配图"></p><p>Ramp 的支出数据显示，AI 使用量仍在攀升，但企业 AI 支出已经停滞，降价与更精细的成本控制是主因。这一信号出现在 Anthropic 临近 IPO 的节点，可能动摇投资者对 AI 超高速增长的假设。对读者：评估 AI 赛道估值时，应把「用量增长」与「付费增长」分开看，关注按 token 计价的通缩风险。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/06/ramp-data-shows-ai-spending-stalling-just-as-anthropic-nears-its-ipo/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="palo-alto-networks-洽谈-5-亿美元收购-ai-agent-安全公司-clutch" tabindex="-1">Palo Alto Networks 洽谈 5 亿美元收购 AI Agent 安全公司 Clutch <a class="header-anchor" href="#palo-alto-networks-洽谈-5-亿美元收购-ai-agent-安全公司-clutch" aria-label="Permalink to &quot;Palo Alto Networks 洽谈 5 亿美元收购 AI Agent 安全公司 Clutch&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c8f8d40813ab.webp" alt="配图"></p><p>Palo Alto Networks 正与 AI Agent 安全初创公司 Clutch 洽谈收购，交易金额约 5 亿美元；Clutch 此前由 Lightspeed 与 SignalFire 投资，上一轮估值仅 8500 万美元。Agent 身份与权限安全正成为大厂并购热点。对读者：若在做 Agent 产品，应尽早梳理凭证管理与审计链路，这类能力正被安全厂商溢价收购。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/05/palo-alto-networks-in-talks-to-buy-ai-agent-security-startup-clutch-for-500m/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-承诺数据中心项目不再对公职人员使用-nda" tabindex="-1">OpenAI 承诺数据中心项目不再对公职人员使用 NDA <a class="header-anchor" href="#openai-承诺数据中心项目不再对公职人员使用-nda" aria-label="Permalink to &quot;OpenAI 承诺数据中心项目不再对公职人员使用 NDA&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/1cf3ac28c8f3.jpg" alt="配图"></p><p>在中选选民普遍反对数据中心扩张之后，OpenAI 宣布对数据中心所在社区的新承诺，包括不再与公职人员签署保密协议，仅保留涉及安全信息、商业秘密等狭窄范围的保护条款。数据中心选址的社区与监管阻力正在上升。对读者：关注 AI 基建项目的合规与社区沟通成本，这类非技术风险会直接影响算力供给节奏。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1028454/openai-data-center-nda" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="perplexity-推出常驻型工作-agent「teammates」" tabindex="-1">Perplexity 推出常驻型工作 Agent「Teammates」 <a class="header-anchor" href="#perplexity-推出常驻型工作-agent「teammates」" aria-label="Permalink to &quot;Perplexity 推出常驻型工作 Agent「Teammates」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/2db47a23a1d4.jpg" alt="配图"></p><p>Perplexity 发布面向工作场景的常驻 AI Agent「Teammates」，可在同一工作区内同时承担多个角色，并复用已有的项目、技能与记忆。它构建在 Perplexity Computer 之上，支持并行分配任务，直接对标 OpenAI 与 Anthropic 的 Agent 产品。对读者：多 Agent 协作产品的差异点正从模型能力转向记忆与任务编排，选型时应重点测试上下文继承与并发稳定性。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1028302/perplexity-teammates-ai-agents-work" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="亚马逊允许用户发短信给-alexa-下单购物" tabindex="-1">亚马逊允许用户发短信给 Alexa 下单购物 <a class="header-anchor" href="#亚马逊允许用户发短信给-alexa-下单购物" aria-label="Permalink to &quot;亚马逊允许用户发短信给 Alexa 下单购物&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/726e49168efb.jpg" alt="配图"></p><p>亚马逊为 Alexa for Shopping 增加短信购物能力：用户可描述商品或发送照片，Alexa 会在亚马逊商品中检索匹配结果、回复推荐并代为下单。该功能将在数周内推送给数百万用户，延续今年 5 月上线的购物体验。对读者：对话式商务的入口正从 App 转向短信等轻渠道，做电商集成时值得预留消息通道能力。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1028587/amazon-alexa-shopping-ai-text-orders" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="airbnb-计划-2027-年上半年推出-ai-旅行-agent" tabindex="-1">Airbnb 计划 2027 年上半年推出 AI 旅行 Agent <a class="header-anchor" href="#airbnb-计划-2027-年上半年推出-ai-旅行-agent" aria-label="Permalink to &quot;Airbnb 计划 2027 年上半年推出 AI 旅行 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d2c79caf1195.jpg" alt="配图"></p><p>Airbnb 在 Q3 2026 股东信中宣布，将于 2027 年上半年推出 AI 旅行 Agent，帮助用户规划行程、比较选项、管理预订并在住宿期间提供协助。公司称现有 Agent 只擅长订餐厅等简单任务，而旅行规划需要专门构建的新界面。对读者：垂直场景 Agent 的壁垒在交易闭环与供给数据，而非通用推理能力。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1028412/airbnb-ai-travel-agent-q3-2026-earnings" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-与-hacktron-合作排查自身系统漏洞" tabindex="-1">OpenAI 与 Hacktron 合作排查自身系统漏洞 <a class="header-anchor" href="#openai-与-hacktron-合作排查自身系统漏洞" aria-label="Permalink to &quot;OpenAI 与 Hacktron 合作排查自身系统漏洞&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/f6acb2b67618.webp" alt="配图"></p><p>OpenAI 宣布与安全公司 Hacktron 合作，寻找其系统漏洞、测试与第三方服务的连接安全性，并借助前沿 AI 强化防御。这延续了模型厂商引入外部安全力量做红队与供应链审计的趋势。对读者：接入第三方服务的 AI 产品应把外部渗透测试纳入常规流程，尤其是 OAuth 与工具调用链路。</p><p class="news-entry-source"><a href="https://openai.com/index/partnering-with-hacktron" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gemini-omni-1-2-flash-发布-原生-15-秒视频、降价-30" tabindex="-1">Gemini Omni 1.2 Flash 发布：原生 15 秒视频、降价 30% <a class="header-anchor" href="#gemini-omni-1-2-flash-发布-原生-15-秒视频、降价-30" aria-label="Permalink to &quot;Gemini Omni 1.2 Flash 发布：原生 15 秒视频、降价 30%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/76e3d0235ac5.png" alt="配图"></p><p>Google 发布 Gemini Omni 1.2 Flash，支持原生 15 秒视频生成与多轮对话式编辑，一致性与可控性提升，价格下调 30%，720p 视频约每秒 0.07 美元。视频生成的成本曲线继续下探。对读者：做视频类功能时可重新核算单位成本，短片段生成已接近可规模化商用的价位。</p><p class="news-entry-source"><a href="https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="thinking-machines-发布-inkling-2-small-594b-moe、17b-激活" tabindex="-1">Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活 <a class="header-anchor" href="#thinking-machines-发布-inkling-2-small-594b-moe、17b-激活" aria-label="Permalink to &quot;Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-06">2026-11-06</time></p><p>Thinking Machines Lab 发布 Inkling 2 Small，总参数 594B、激活参数 17B 的 MoE 模型，在 Artificial Analysis 智能指数上得分 31，可通过 Tinker 运行，并计划以 Apache 2.0 开放权重。稀疏 MoE 继续以低激活成本冲击中端市场。对读者：评估自托管方案时，应把激活参数与显存占用而非总参数作为部署成本基准。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/05/thinking-machines-inkling-2-small-release/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="百度开源-ernie-5-5-flash-base-280b-moe、14b-激活" tabindex="-1">百度开源 ERNIE 5.5 Flash Base：280B MoE、14B 激活 <a class="header-anchor" href="#百度开源-ernie-5-5-flash-base-280b-moe、14b-激活" aria-label="Permalink to &quot;百度开源 ERNIE 5.5 Flash Base：280B MoE、14B 激活&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-06">2026-11-06</time></p><p>百度发布 ERNIE 5.5 Flash Base，280B 稀疏 MoE 基座模型，激活参数 14B，训练语料 33.5T token，且在任何中期或后期训练之前即公开。基座权重开放有利于二次微调与评测复现。对读者：需要领域微调的团队可优先在开放基座上验证，再决定是否投入后训练算力。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/05/baidu-ernie-5-5-flash-base-280b-moe/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="anthropic-拆解-agent-记忆的组成-用「做梦」整理与纠错" tabindex="-1">Anthropic 拆解 Agent 记忆的组成：用「做梦」整理与纠错 <a class="header-anchor" href="#anthropic-拆解-agent-记忆的组成-用「做梦」整理与纠错" aria-label="Permalink to &quot;Anthropic 拆解 Agent 记忆的组成：用「做梦」整理与纠错&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Anthropic Engineering</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d4be0c3efea6.jpg" alt="配图"></p><p>Anthropic 工程博客讨论为 Claude 设计记忆机制的难点：Agent 必须在不知道后续任务的情况下判断什么值得记住。文章介绍「dreaming」机制如何帮助模型组织记忆、修正错误，并给出记忆组件的拆解思路。对读者：自建 Agent 记忆时，可把「写入策略」与「离线整理」分开设计，避免上下文无限膨胀。</p><p class="news-entry-source"><a href="https://www.anthropic.com/research/components-of-agent-memory" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="github-新-git-存储架构-支撑数千-agent-同时推送" tabindex="-1">GitHub 新 Git 存储架构：支撑数千 Agent 同时推送 <a class="header-anchor" href="#github-新-git-存储架构-支撑数千-agent-同时推送" aria-label="Permalink to &quot;GitHub 新 Git 存储架构：支撑数千 Agent 同时推送&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-11-06">2026-11-06</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/1409d7c48179.png" alt="配图"></p><p>GitHub 详解其新的 Git 存储架构，目标是让数千个 Agent 能同时向同一个仓库推送。这反映出编码 Agent 大规模并行写入正在改变代码托管的底层假设。对读者：若在流水线中批量运行 Agent，应关注并发推送、冲突合并与仓库锁策略的变化。</p><p class="news-entry-source"><a href="https://github.blog/engineering/architecture-optimization/inside-githubs-new-git-storage-architecture/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",i]]);export{d as __pageData,g as default};
